(() => {
  const S = window.Schematic;
  const curves = [["out", "Respond", "--ease-out"], ["outExpo", "Enter", "--ease-out-expo"], ["in", "Exit", "--ease-in"], ["inOut", "Travel", "--ease-in-out"], ["overshoot", "Confirm", "--ease-overshoot"], ["springSmooth", "Smooth spring", "--spring-smooth"], ["springSnappy", "Snappy spring", "--spring-snappy"], ["springBouncy", "Bouncy spring", "--spring-bouncy"], ["linear", "Linear reference", "linear"]];
  const graph = (fn) => Array.from({ length: 121 }, (_, i) => `${i ? "L" : "M"}${30 + i * 2.5},${180 - fn(i / 120) * 140}`).join(" ");
  const simulate = (k, damping, mass) => {
    const dt = 1 / 240, samples = [[0, 0]]; let x = 0, v = 0, t = 0;
    while (t < 4) { v += (-k * (x - 1) - damping * v) / mass * dt; x += v * dt; t += dt; samples.push([t, x]); if (t > .2 && Math.abs(x - 1) < .001 && Math.abs(v) < .01) break; }
    const values = Array.from({ length: 81 }, (_, i) => i === 80 ? 1 : samples[Math.min(samples.length - 1, Math.round(i / 80 * (samples.length - 1)))][1]);
    return { duration: Math.round(t * 1000), values, css: `linear(${values.map((v) => +v.toFixed(4)).join(", ")})` };
  };
  S.page({
    id: "motion", title: "Motion Lab", group: "Foundations", icon: "wave", order: 20,
    description: "Inspect curves, tune physical springs and replay purposeful choreography.",
    render: () => `<div class="pg-motion">
      ${S.pageHead({ icon: "wave", eyebrow: "Foundations / 02", title: "Make change feel natural.", lead: "A control responds. An object travels. A result settles. Give each action the curve it needs, and let the interface keep up with the hand.", meta: ['<span class="badge badge-accent">Interruptible by design</span>', '<span class="badge">Reduced-motion aware</span>'] })}
      ${S.section({ id: "motion-curves", num: "01", title: "The curve is the character", desc: "Compare the same journey under different curves. Scrub time to inspect a single frame. The straight line is a reference, not the default.", body: S.demo({ title: "Easing workbench", desc: "An out-curve responds quickly and settles gently. A spring carries momentum through the destination.", replay: true, stage: "is-plain is-col", specs: ["transform", "requestAnimationFrame"], body: `<div class="ml-workbench"><div class="ml-graph"><svg viewBox="0 0 360 220" role="img" aria-label="Easing curve: time left to right, progress bottom to top"><path class="ml-grid" d="M30 40H330M30 110H330M30 180H330M30 40V180M180 40V180M330 40V180"/><path class="ml-reference" d="M30 180L330 40"/><path class="ml-path" id="motion-path"/><circle class="ml-point" id="motion-point" r="5" cx="30" cy="180"/><text x="30" y="205">0</text><text x="300" y="205">time →</text><text x="8" y="44">1</text><text x="8" y="184">0</text></svg></div><div class="stack ml-settings"><label class="stack" for="motion-curve"><span class="t-small">Curve</span><select id="motion-curve">${curves.map(([key, label]) => `<option value="${key}">${label}</option>`).join("")}</select></label><label class="stack" for="motion-duration"><span class="row-between t-small">Duration <output id="motion-duration-val">600ms</output></span><input class="range" type="range" id="motion-duration" min="150" max="1400" step="50" value="600"></label><button class="btn btn-primary" id="motion-play">${S.icon("play")} Replay curve</button><code class="ml-token" id="motion-token">--ease-out</code></div></div><div class="ml-track" aria-hidden="true"><span class="ml-ghost"></span><span class="ml-traveller" id="motion-traveller">${S.icon("cube", { size: 20 })}</span></div><div class="ml-scrub"><label for="motion-scrub" class="t-caption">Scrub time</label><input class="range" type="range" id="motion-scrub" min="0" max="1000" value="0"><output class="t-mono t-caption" id="motion-readout">0% → 0%</output></div>` }) })}
      ${S.section({ id: "motion-springs", num: "02", title: "A little physics", desc: "Stiffness pulls toward the destination, damping absorbs momentum, and mass resists acceleration. This simulation exports a sampled CSS linear() curve.", body: S.demo({ title: "Spring bench", desc: "An original mass–spring simulation. Change a parameter and watch it settle; click Copy to take the curve.", stage: "is-plain is-col", replay: true, specs: ["mass / stiffness / damping"], body: `<div class="ml-spring-stage"><span class="ml-spring-line"></span><span class="ml-spring-object" id="motion-spring-object">${S.icon("layers", { size: 28 })}</span><span class="ml-spring-goal"></span></div><div class="grid cols-3 ml-spring-controls">${[["stiffness", "Stiffness", 80, 600, 300, 10], ["damping", "Damping", 8, 60, 26, 1], ["mass", "Mass", .5, 2.5, 1, .1]].map(([id, label, min, max, val, step]) => `<label class="stack" for="motion-${id}"><span class="row-between t-small">${label}<output id="motion-${id}-val">${val}</output></span><input class="range" type="range" id="motion-${id}" min="${min}" max="${max}" value="${val}" step="${step}"></label>`).join("")}</div><div class="row-between ml-spring-actions"><span class="t-caption" id="motion-spring-time">Settles in 600ms</span><div class="row"><button class="btn btn-secondary" id="motion-spring-replay">${S.icon("refresh")} Replay</button><button class="btn btn-soft" id="motion-spring-copy">${S.icon("copy")} Copy curve</button></div></div>` }) })}
      ${S.section({ id: "motion-choreography", num: "03", title: "Cause, then consequence", desc: "A short stagger shows order without making the user wait for a performance. Interrupt a sequence by replaying it: the new intent wins.", body: `<div class="grid cols-2">${S.demo({ title: "Staggered arrival", desc: "A group arrives as one idea, then resolves into its parts.", replay: true, specs: ["32ms stagger", "ease-out-expo"], body: `<div class="ml-list" id="motion-list">${[["document", "Read the brief", "Requirements aligned"], ["droplet", "Apply the language", "Tokens connected"], ["check-circle", "Review the details", "Ready to build"]].map(([ic, t, d], i) => `<div class="ml-list-row" style="--i:${i}"><span class="ml-list-icon">${S.icon(ic)}</span><div><strong>${t}</strong><div class="t-caption">${d}</div></div><span class="badge badge-success">0${i + 1}</span></div>`).join("")}</div>` })}${S.demo({ title: "State continuity", desc: "A moving indicator and directional content keep the relationship visible.", specs: ["spring-snappy", "direction-aware"], body: `<div class="ml-continuity"><div class="seg" id="motion-state">${["Design", "Build", "Review"].map((s, i) => `<button class="seg-btn" data-value="${i}">${s}</button>`).join("")}</div><div class="ml-state-content" id="motion-state-content" role="status"><span class="ml-state-icon">${S.icon("droplet", { size: 28 })}</span><strong>Start with a shared language.</strong><p class="t-caption">Decisions become reusable tokens.</p></div></div>` })}</div>` })}
      ${S.section({ id: "motion-performance", num: "04", title: "Speed is part of the design", desc: "The prototype ships its pages together. It builds inactive DOM during idle time and on link intent; mounted pages keep their form state and scroll position.", body: `<div class="card stack ml-performance"><div class="row-between"><span class="t-h3">Local page cache</span><button class="btn btn-secondary btn-sm" id="motion-cache-refresh">${S.icon("refresh")} Inspect</button></div><div id="motion-cache" class="ml-cache"></div><p class="t-caption">These are real local cache states. No server request or speculative network prefetch is required for this prototype.</p></div><div class="grid cols-3">${[["arrow-right", "Enter with out", "Let the first frame acknowledge intent. Use out or out-expo, and keep distance short."], ["logout", "Exit with in", "An exit should clear the way. Use an in-curve and roughly 30% less time."], ["eye", "Respect the preference", "Use the tune panel to inspect slow motion or reduce spatial motion. User action timings stay usable."]].map(([ic, t, d]) => `<div class="card stack"><span class="accent-text">${S.icon(ic)}</span><h3 class="t-h3">${t}</h3><p class="t-small muted">${d}</p></div>`).join("")}</div>` })}
    </div>`,
    mount(root) {
      const q = (s) => S.$(s, root), state = root._motion = { curve: "out", progress: 0, tween: null, spring: null, animations: [] };
      const curve = q("#motion-curve"), duration = q("#motion-duration"), scrub = q("#motion-scrub"), traveller = q("#motion-traveller");
      const position = (t) => { const v = S.ease[state.curve](t); state.progress = t; q("#motion-point").setAttribute("cx", 30 + t * 300); q("#motion-point").setAttribute("cy", 180 - v * 140); traveller.style.transform = `translateX(${Math.max(0, q(".ml-track").clientWidth - 48) * v}px)`; scrub.value = Math.round(t * 1000); q("#motion-readout").textContent = `${Math.round(t * 100)}% → ${Math.round(v * 100)}%`; };
      const updateCurve = () => { state.curve = curve.value; q("#motion-path").setAttribute("d", graph(S.ease[state.curve])); q("#motion-token").textContent = curves.find(([k]) => k === state.curve)[2]; };
      state.play = () => { state.tween?.cancel(); updateCurve(); state.tween = S.tween({ from: 0, to: 1, duration: +duration.value, ease: S.ease.linear, onUpdate: position }); };
      q("#motion-play").addEventListener("click", state.play); curve.addEventListener("change", state.play);
      duration.addEventListener("input", () => { q("#motion-duration-val").textContent = `${duration.value}ms`; }); duration.addEventListener("change", state.play);
      scrub.addEventListener("input", () => { state.tween?.cancel(); position(+scrub.value / 1000); });
      new ResizeObserver(() => position(state.progress)).observe(q(".ml-track"));
      let physical;
      state.playSpring = () => {
        physical = simulate(+q("#motion-stiffness").value, +q("#motion-damping").value, +q("#motion-mass").value);
        q("#motion-spring-time").textContent = `Simulation: ${physical.duration}ms${S.reduced() ? " / reduced motion" : ""}`;
        state.spring?.cancel();
        const distance = q(".ml-spring-stage").clientWidth - 80;
        state.spring = q("#motion-spring-object").animate([{ transform: "translateX(0)" }, { transform: `translateX(${distance}px)` }], { duration: S.dur(physical.duration), easing: physical.css, fill: "forwards" });
      };
      ["stiffness", "damping", "mass"].forEach((id) => q(`#motion-${id}`).addEventListener("input", () => { q(`#motion-${id}-val`).textContent = q(`#motion-${id}`).value; state.playSpring(); }));
      q("#motion-spring-replay").addEventListener("click", state.playSpring);
      q("#motion-spring-copy").addEventListener("click", async () => { physical ||= simulate(300, 26, 1); const ok = await S.copy(`transition: transform ${physical.duration}ms ${physical.css};\n/* Multiply duration by your motion preference; suppress spatial motion when reduced. */`); S.toast({ title: ok ? "Spring curve copied" : "Clipboard unavailable", tone: ok ? "success" : "warning" }); });
      state.choreograph = () => { state.animations.forEach((a) => a.cancel()); state.animations = S.$$(".ml-list-row", root).map((el, i) => el.animate([{ opacity: 0, transform: S.reduced() ? "none" : "translateY(12px)" }, { opacity: 1, transform: "none" }], { duration: S.dur(460), delay: S.dur(i * 32), easing: S.curve.outExpo, fill: "backwards" })); };
      let previous = 0, contentAnimation;
      const copy = [["droplet", "Start with a shared language.", "Decisions become reusable tokens."], ["cube", "Compose familiar parts.", "Components carry the same behaviour."], ["check-circle", "Check the whole experience.", "Keyboard, motion and responsive layouts."]];
      S.segmented(q("#motion-state"), { value: "0", onChange: (v) => { const index = +v, [ic, title, desc] = copy[index], el = q("#motion-state-content"); contentAnimation?.cancel(); el.innerHTML = `<span class="ml-state-icon">${S.icon(ic, { size: 28 })}</span><strong>${title}</strong><p class="t-caption">${desc}</p>`; contentAnimation = el.animate([{ opacity: 0, transform: `translateX(${S.reduced() ? 0 : index >= previous ? 12 : -12}px)` }, { opacity: 1, transform: "none" }], { duration: S.dur(320), easing: S.curve.out }); previous = index; } });
      state.cache = () => { q("#motion-cache").innerHTML = S.pages.map((p) => `<div class="ml-cache-row"><span>${S.icon(p.icon, { size: 14 })} ${S.esc(p.title)}</span><span class="badge ${S._shell.state.mounted.has(p.id) ? "badge-success" : "badge-accent"}">${S._shell.state.mounted.has(p.id) ? "Mounted" : S._shell.state.built.has(p.id) ? "Prepared" : "On intent"}</span></div>`).join(""); };
      q("#motion-cache-refresh").addEventListener("click", state.cache);
      root.addEventListener("replay", (e) => { if (e.target.contains(q("#motion-play"))) state.play(); else if (e.target.contains(q("#motion-spring-object"))) state.playSpring(); else state.choreograph(); });
      updateCurve(); position(0); state.cache();
    },
    enter(root) { root._motion.play(); root._motion.playSpring(); root._motion.choreograph(); root._motion.cache(); },
    leave(root) { const s = root._motion; s.tween?.cancel(); s.spring?.cancel(); s.animations.forEach((a) => a.cancel()); },
  });
})();
